-- =====================================================================================================
-- Manual database upgrade script for migration 202608190725064_AddCopilotUsageReports
--
-- For DBAs who upgrade the database by hand instead of running the installer
-- (AnalyticsInstaller.exe --initdb / DatabaseUpgrader.CheckDbUpgraded).
--
-- What it does:
--   1. Creates the three Microsoft 365 Copilot usage-report tables (see below).
--   2. Records the migration in dbo.__MigrationHistory so Entity Framework and the web app's Health
--      page treat it as applied.
--
-- Tables created:
--   dbo.copilot_user_count_log           - tenant enabled-vs-active Copilot user counts (narrow/tall:
--                                          one row per report type / period / date / app).
--   dbo.copilot_usage_user_activity_log  - per-user Copilot usage, one row per user per snapshot date.
--   dbo.copilot_usage_report_import_log  - one row per report import, including whether the tenant
--                                          concealed user identities.
--
-- Cost and safety:
--   These are three new, EMPTY tables, so every statement is metadata-only and completes in
--   milliseconds no matter how large the tenant is. No maintenance window is required and no existing
--   table is rewritten; the only lock taken on existing data is a brief schema lock on dbo.users to
--   create the foreign key. The script is fully guarded and idempotent - re-running it is a no-op.
--
-- Prerequisite: migration 202608131055001_IndexReportDateQueries must already be applied.
-- =====================================================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @migration nvarchar(100) = N'202608190725064_AddCopilotUsageReports';
DECLARE @predecessor nvarchar(100) = N'202608131055001_IndexReportDateQueries';
DECLARE @msg nvarchar(2000);

IF OBJECT_ID(N'dbo.__MigrationHistory', N'U') IS NULL
BEGIN
    RAISERROR('AddCopilotUsageReports: dbo.__MigrationHistory does not exist - this does not look like an Analytics database. Nothing was changed.', 16, 1);
    RETURN;
END

IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = @predecessor)
BEGIN
    SET @msg = N'AddCopilotUsageReports: prerequisite migration ' + @predecessor
        + N' is not recorded in __MigrationHistory. Upgrade to the previous release first, or run the installer to reconcile. Nothing was changed.';
    RAISERROR(@msg, 16, 1);
    RETURN;
END

IF OBJECT_ID(N'dbo.users', N'U') IS NULL
BEGIN
    RAISERROR('AddCopilotUsageReports: dbo.users does not exist, so the per-user table cannot be created. Nothing was changed.', 16, 1);
    RETURN;
END

-- -----------------------------------------------------------------------------------------------------
-- 1. Tables
-- -----------------------------------------------------------------------------------------------------

IF OBJECT_ID(N'dbo.copilot_usage_report_import_log', N'U') IS NULL
BEGIN
    RAISERROR('AddCopilotUsageReports: creating dbo.copilot_usage_report_import_log.', 0, 1) WITH NOWAIT;
    CREATE TABLE [dbo].[copilot_usage_report_import_log]
    (
        [id] [int] NOT NULL IDENTITY,
        [report_name] [nvarchar](100),
        [report_refresh_date] [datetime],
        [report_version] [nvarchar](10),
        [report_period] [nvarchar](10),
        [imported_utc] [datetime] NOT NULL,
        [rows_read] [int] NOT NULL,
        [rows_saved] [int] NOT NULL,
        [is_upn_obfuscated] [bit] NOT NULL,
        [error] [nvarchar](1000),
        CONSTRAINT [PK_dbo.copilot_usage_report_import_log] PRIMARY KEY ([id])
    );
END
ELSE
    RAISERROR('AddCopilotUsageReports: dbo.copilot_usage_report_import_log already exists, skipping.', 0, 1) WITH NOWAIT;

IF OBJECT_ID(N'dbo.copilot_usage_user_activity_log', N'U') IS NULL
BEGIN
    RAISERROR('AddCopilotUsageReports: creating dbo.copilot_usage_user_activity_log.', 0, 1) WITH NOWAIT;
    CREATE TABLE [dbo].[copilot_usage_user_activity_log]
    (
        [id] [int] NOT NULL IDENTITY,
        [report_period_days] [int] NOT NULL,
        [prompts_all_apps] [int],
        [prompts_chat_work] [int],
        [prompts_chat_web] [int],
        [active_usage_days] [int],
        [chat_last_activity_date] [datetime],
        [teams_last_activity_date] [datetime],
        [word_last_activity_date] [datetime],
        [excel_last_activity_date] [datetime],
        [powerpoint_last_activity_date] [datetime],
        [outlook_last_activity_date] [datetime],
        [onenote_last_activity_date] [datetime],
        [loop_last_activity_date] [datetime],
        [chat_work_last_activity_date] [datetime],
        [chat_web_last_activity_date] [datetime],
        [m365_copilot_last_activity_date] [datetime],
        [edge_last_activity_date] [datetime],
        [agent_last_activity_date] [datetime],
        [is_upn_obfuscated] [bit] NOT NULL,
        [user_id] [int] NOT NULL,
        [date] [datetime] NOT NULL,
        [last_activity_date] [datetime],
        CONSTRAINT [PK_dbo.copilot_usage_user_activity_log] PRIMARY KEY ([id])
    );
END
ELSE
    RAISERROR('AddCopilotUsageReports: dbo.copilot_usage_user_activity_log already exists, skipping.', 0, 1) WITH NOWAIT;

IF OBJECT_ID(N'dbo.copilot_user_count_log', N'U') IS NULL
BEGIN
    RAISERROR('AddCopilotUsageReports: creating dbo.copilot_user_count_log.', 0, 1) WITH NOWAIT;
    CREATE TABLE [dbo].[copilot_user_count_log]
    (
        [id] [int] NOT NULL IDENTITY,
        [report_refresh_date] [datetime] NOT NULL,
        [report_date] [datetime] NOT NULL,
        [report_type] [nvarchar](20),
        [report_period_days] [int],
        [app_name] [nvarchar](100),
        [enabled_users] [int] NOT NULL,
        [active_users] [int] NOT NULL,
        [prompts_submitted] [bigint],
        [average_prompts_submitted] [float],
        CONSTRAINT [PK_dbo.copilot_user_count_log] PRIMARY KEY ([id])
    );
END
ELSE
    RAISERROR('AddCopilotUsageReports: dbo.copilot_user_count_log already exists, skipping.', 0, 1) WITH NOWAIT;

-- -----------------------------------------------------------------------------------------------------
-- 2. Indexes and foreign key
--    Both indexes are UNIQUE and functional: they are the keys the importer upserts on, which is what
--    stops a re-imported overlapping window from duplicating rows.
-- -----------------------------------------------------------------------------------------------------

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.copilot_usage_user_activity_log') AND name = N'IX_date_user_id_report_period_days')
BEGIN
    RAISERROR('AddCopilotUsageReports: creating IX_date_user_id_report_period_days.', 0, 1) WITH NOWAIT;
    CREATE UNIQUE INDEX [IX_date_user_id_report_period_days] ON [dbo].[copilot_usage_user_activity_log] ([date], [user_id], [report_period_days]);
END

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N'dbo.copilot_user_count_log') AND name = N'IX_report_type_report_period_days_report_date_app_name')
BEGIN
    RAISERROR('AddCopilotUsageReports: creating IX_report_type_report_period_days_report_date_app_name.', 0, 1) WITH NOWAIT;
    CREATE UNIQUE INDEX [IX_report_type_report_period_days_report_date_app_name] ON [dbo].[copilot_user_count_log] ([report_type], [report_period_days], [report_date], [app_name]);
END

IF NOT EXISTS (SELECT 1 FROM sys.foreign_keys WHERE name = N'FK_dbo.copilot_usage_user_activity_log_dbo.users_user_id')
BEGIN
    RAISERROR('AddCopilotUsageReports: creating the foreign key to dbo.users.', 0, 1) WITH NOWAIT;
    ALTER TABLE [dbo].[copilot_usage_user_activity_log]
        ADD CONSTRAINT [FK_dbo.copilot_usage_user_activity_log_dbo.users_user_id]
        FOREIGN KEY ([user_id]) REFERENCES [dbo].[users] ([id]) ON DELETE CASCADE;
END

-- -----------------------------------------------------------------------------------------------------
-- 3. Record the migration in __MigrationHistory.
--
--    Unlike the recent index-only migrations, this one CHANGES the Entity Framework model, so the stamp
--    cannot copy the predecessor's Model blob - Entity Framework would then see the new tables as pending
--    model changes and try to create them again on the next upgrade. The correct snapshot for this
--    migration is therefore embedded below: it is the base64 of the gzipped EDMX that Entity Framework
--    itself generated (the 'Target' resource of 202608190725064_AddCopilotUsageReports.resx),
--    appended in chunks because a single SQL string literal is capped at 4000 characters.
--
--    ContextKey is copied from the predecessor row (it describes the context type, which this migration does
--    not change). ProductVersion is set explicitly to the Entity Framework version that generated this
--    snapshot, so a by-hand upgrade records the same value an installer-driven upgrade would.
-- -----------------------------------------------------------------------------------------------------

IF NOT EXISTS (SELECT 1 FROM dbo.__MigrationHistory WHERE MigrationId = @migration)
BEGIN
    DECLARE @modelBase64 nvarchar(max) = N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';
    SET @modelBase64 = @modelBase64 + N'';

    DECLARE @model varbinary(max) =
        CAST(N'<m>' + @modelBase64 + N'</m>' AS xml).value('(/m)[1]', 'varbinary(max)');

    INSERT INTO dbo.__MigrationHistory (MigrationId, ContextKey, Model, ProductVersion)
    SELECT @migration, ContextKey, @model, N'6.5.2'
    FROM dbo.__MigrationHistory
    WHERE MigrationId = @predecessor;

    RAISERROR('AddCopilotUsageReports: recorded in __MigrationHistory.', 0, 1) WITH NOWAIT;
END
ELSE
    RAISERROR('AddCopilotUsageReports: already recorded in __MigrationHistory, nothing to do.', 0, 1) WITH NOWAIT;

RAISERROR('AddCopilotUsageReports: finished.', 0, 1) WITH NOWAIT;
